# WITH "
# MATCH (n1:CTCatalogue)
# MATCH (n2:CTCodelistRoot)-[r1:HAS_ATTRIBUTES_ROOT]->(n3:CTCodelistAttributesRoot)-[r2:LATEST]->(n4:CTCodelistAttributesValue)
# WHERE n4.submission_value = 'DATATYPE'
# OPTIONAL MATCH (n1)-[r3:HAS_CODELIST]->(n2)
# RETURN * limit 1000
#  " AS query
#  CALL apoc.export.cypher.query(query, null, {stream: true, format: "plain",  cypherFormat: "updateAll",ifNotExists: true})
#  YIELD cypherStatements, file, batches, source, format, nodes, relationships, time, rows, batchSize
#  RETURN cypherStatements, file, batches, source, format, nodes, relationships, time, rows, batchSize;
SDTM_CATALOGUE_TO_DATATYPE_CODELIST = """
UNWIND [{_id:849981, properties:{}}] AS row
MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:CTCodelistAttributesRoot;
UNWIND [{_id:2565131, properties:{name:"MRCT CT"}}, {_id:2565132, properties:{name:"GLOSSARY CT"}}, {_id:2565133, properties:{name:"COA CT"}}, {_id:2565134, properties:{name:"SDTM CT"}}, {_id:2565135, properties:{name:"DEFINE-XML CT"}}, {_id:2565136, properties:{name:"SEND CT"}}, {_id:2565137, properties:{name:"DDF CT"}}, {_id:2565138, properties:{name:"CDASH CT"}}, {_id:2565139, properties:{name:"ADAM CT"}}, {_id:2565140, properties:{name:"PROTOCOL CT"}}, {_id:2565141, properties:{name:"QS-FT CT"}}, {_id:2565142, properties:{name:"TMF CT"}}, {_id:2565143, properties:{name:"QRS CT"}}] AS row
MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:CTCatalogue;
UNWIND [{_id:849982, properties:{preferred_term:"Data type", codelist_type:"Standard", name:"Data type", definition:"Data type for ODM metadata", extensible:true, submission_value:"DATATYPE"}}] AS row
MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:CTCodelistAttributesValue;
UNWIND [{uid:"CTCodelist_000028", properties:{}}] AS row
MERGE (n:CTCodelistRoot{uid: row.uid}) SET n += row.properties;
UNWIND [{start: {_id:849981}, end: {_id:849982}, properties:{}}] AS row
MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:LATEST]->(end) SET r += row.properties;
UNWIND [{start: {uid:"CTCodelist_000028"}, end: {_id:849981}, properties:{}}] AS row
MATCH (start:CTCodelistRoot{uid: row.start.uid})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:HAS_ATTRIBUTES_ROOT]->(end) SET r += row.properties;
UNWIND [{start: {_id:2565134}, end: {uid:"CTCodelist_000028"}, properties:{}}] AS row
MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
MATCH (end:CTCodelistRoot{uid: row.end.uid})
MERGE (start)-[r:HAS_CODELIST]->(end) SET r += row.properties;
MATCH (n:`UNIQUE IMPORT LABEL`)  WITH n LIMIT 20000 REMOVE n:`UNIQUE IMPORT LABEL` REMOVE n.`UNIQUE IMPORT ID`;
"""

